    //Driver Code Starts
#include <iostream>
#include<vector>
using namespace std;
//Driver Code Ends


int numberOfWays(int n) {

    if (n == 0 || n == 1) return 1;

    // Create a 1D DP array to store results of subproblems
    vector<int> dp(n + 1);

    // Initialize base cases
    dp[0] = 1;  
    dp[1] = 1;

    // Build the solution iteratively (Bottom-Up DP)
    for (int i = 2; i <= n; i++) {
        // Two choices:
        dp[i] = dp[i - 1] + dp[i - 2];
    }

    return dp[n];
}


